package routing

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Request is the routing input. All fields are optional except at least
// one of {Profile, ModelRef, Model, Harness, Provider} should be set
// (otherwise the engine has nothing to disambiguate on).
//
// Provider is present from day one (fixes ddx-8610020e — no soft-preference
// dropping).
type Request struct {
	Profile            string // "cheap" | "standard" | "smart"
	ModelRef           string // catalog alias (e.g. "qwen/qwen3.6")
	Model              string // exact concrete model pin
	Provider           string // exact provider pin; constrains routing to one provider identity
	Harness            string // hard preference; constrains routing to one harness
	Reasoning          string // public reasoning scalar
	Permissions        string // "safe" | "supervised" | "unrestricted"
	ProviderPreference string // "local-first" | "subscription-first" | "local-only" | "subscription-only"

	// EstimatedPromptTokens, when > 0, drives context-window gating.
	EstimatedPromptTokens int

	// RequiresTools, when true, requires the candidate to support tool calling.
	RequiresTools bool
	MinPower      int
	MaxPower      int
}

const (
	ProviderPreferenceLocalFirst        = "local-first"
	ProviderPreferenceSubscriptionFirst = "subscription-first"
	ProviderPreferenceLocalOnly         = "local-only"
	ProviderPreferenceSubscriptionOnly  = "subscription-only"

	ContextSourceProviderAPI    = "provider_api"
	ContextSourceProviderConfig = "provider_config"
	ContextSourceCatalog        = "catalog"
	ContextSourceDefault        = "default"
	ContextSourceUnknown        = "unknown"
)

// MinContextWindow returns the minimum context window the request requires,
// derived from EstimatedPromptTokens with a safety margin.
func (r Request) MinContextWindow() int {
	if r.EstimatedPromptTokens <= 0 {
		return 0
	}
	// 1.25x safety margin for response tokens + tool overhead.
	return r.EstimatedPromptTokens + r.EstimatedPromptTokens/4
}

const (
	QuotaTrendUnknown    = "unknown"
	QuotaTrendHealthy    = "healthy"
	QuotaTrendBurning    = "burning"
	QuotaTrendExhausting = "exhausting"
)

// HarnessEntry is the harness-side input the caller (service) supplies.
// It is the routing engine's view of a registered harness; the engine does
// not import the harnesses package directly to keep the dependency narrow.
type HarnessEntry struct {
	Name                string
	Surface             string
	CostClass           string
	IsLocal             bool
	IsSubscription      bool
	IsHTTPProvider      bool
	AutoRoutingEligible bool
	TestOnly            bool
	ExactPinSupport     bool
	DefaultModel        string
	SupportedModels     []string
	SupportedReasoning  []string
	MaxReasoningTokens  int
	SupportedPerms      []string
	SupportsTools       bool

	// Available reflects the harness's discovered availability.
	Available bool

	// QuotaOK / QuotaPercentUsed reflect live quota state (when applicable).
	// SubscriptionOK gates subscription harnesses at the eligibility level:
	// when false, the candidate is ineligible regardless of score.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaStale       bool
	QuotaTrend       string // unknown|healthy|burning|exhausting
	QuotaReason      string
	SubscriptionOK   bool // false = hard gate; true = score-based demotion

	// InCooldown marks the entire harness as being in a failure cooldown.
	// When true the harness is demoted in score (via candidateInternal.InCooldown)
	// but not hard-rejected, so it can still win when all other harnesses are
	// also unavailable.
	InCooldown bool

	// Providers is the list of providers this harness can dispatch to.
	// For subprocess harnesses (claude/codex) this is typically a single
	// vendor entry. For the native "fiz" harness it is the configured
	// list of HTTP providers.
	Providers []ProviderEntry
}

// ProviderEntry describes one provider available under a harness.
type ProviderEntry struct {
	Name                 string
	BaseURL              string
	ServerInstance       string
	EndpointName         string
	EndpointBaseURL      string
	DefaultModel         string
	CostClass            string
	DiscoveredIDs        []string // models discovered via /v1/models or equivalent
	DiscoveryAttempted   bool
	ContextWindows       map[string]int
	ContextWindowSources map[string]string
	ContextWindow        int
	ContextWindowSource  string
	SupportsTools        bool

	// CostUSDPer1kTokens is the estimated blended USD cost per 1,000 tokens.
	// A zero value with CostSourceUnknown means the provider cost is unknown.
	CostUSDPer1kTokens float64
	// CostSource describes where CostUSDPer1kTokens came from: catalog,
	// subscription, user-config, or unknown.
	CostSource string

	// InCooldown reflects whether this provider is in a failure-cooldown window.
	InCooldown bool
}

const (
	// CostSourceCatalog means cost came from the model catalog.
	CostSourceCatalog = "catalog"
	// CostSourceSubscription means cost came from subscription quota pricing.
	CostSourceSubscription = "subscription"
	// CostSourceUnknown means no reliable cost estimate is available.
	CostSourceUnknown = "unknown"
	// CostSourceUserConfig means cost came from explicit user configuration.
	CostSourceUserConfig = "user-config"
)

// Decision is the routing engine's output: the picked candidate plus the
// full ranked list (including rejected ones with rejection reasons).
type Decision struct {
	Harness        string
	Provider       string
	Endpoint       string
	ServerInstance string
	Model          string
	Reason         string
	Candidates     []Candidate
}

// Candidate is one ranked routing option.
type Candidate struct {
	Harness            string
	Provider           string
	Endpoint           string
	ServerInstance     string
	Model              string
	Score              float64
	CostUSDPer1kTokens float64
	CostSource         string
	Power              int
	ContextLength      int
	ContextSource      string
	Eligible           bool
	Reason             string

	// FilterReason is the typed disqualification category, set at the
	// rejection site that decided why this candidate is ineligible.
	// Empty for eligible candidates. Service-layer code maps this to the
	// public FilterReason* string constants without parsing free-form
	// Reason text.
	FilterReason FilterReason

	// LatencyMS, SuccessRate, and CostClass expose the score-component
	// inputs so callers can render per-axis explanations alongside the
	// final Score. Zero / negative values mean unknown (see Inputs docs).
	LatencyMS       float64
	SuccessRate     float64
	CostClass       string
	SpeedTPS        float64
	ContextHeadroom int

	QuotaOK          bool
	QuotaPercentUsed int
	QuotaTrend       string
}

// FilterReason categorizes why a routing candidate was disqualified.
// The zero value (empty string) means the candidate is eligible.
type FilterReason string

const (
	// FilterReasonEligible is the zero value for an eligible candidate.
	FilterReasonEligible FilterReason = ""
	// FilterReasonContextTooSmall: candidate's context window is below the
	// request's MinContextWindow().
	FilterReasonContextTooSmall FilterReason = "context_too_small"
	// FilterReasonNoToolSupport: request needs tool calling but candidate
	// does not support it.
	FilterReasonNoToolSupport FilterReason = "no_tool_support"
	// FilterReasonReasoningUnsupported: candidate cannot satisfy the
	// requested reasoning policy.
	FilterReasonReasoningUnsupported FilterReason = "reasoning_unsupported"
	// FilterReasonUnhealthy: harness/provider is unavailable, in cooldown,
	// out of quota, or excluded by a hard provider-preference gate.
	FilterReasonUnhealthy FilterReason = "unhealthy"
	// FilterReasonScoredBelowTop: catch-all for ineligibility that does
	// not fit a more specific category (also used for capability
	// mismatches such as permissions/model-pin/exact-pin and for model
	// resolution failures).
	FilterReasonScoredBelowTop FilterReason = "scored_below_top"
	// FilterReasonPinMismatch: candidate was rejected because it does not
	// satisfy an explicit caller pin such as Provider.
	FilterReasonPinMismatch FilterReason = "pin_mismatch"
	// FilterReasonPowerMissing: automatic routing requires catalog power
	// metadata, but the candidate model is unknown or has zero power.
	FilterReasonPowerMissing FilterReason = "power_missing"
	// FilterReasonBelowMinPower: candidate model power is below req.MinPower.
	FilterReasonBelowMinPower FilterReason = "below_min_power"
	// FilterReasonAboveMaxPower: candidate model power is above req.MaxPower.
	FilterReasonAboveMaxPower FilterReason = "above_max_power"
	// FilterReasonExactPinOnly: catalog marks the model as only eligible for
	// explicit model pins.
	FilterReasonExactPinOnly FilterReason = "exact_pin_only"
	// FilterReasonNotAutoRoutable: catalog metadata exists but marks the
	// model inactive, deprecated, stale, or otherwise excluded from
	// automatic routing.
	FilterReasonNotAutoRoutable FilterReason = "not_auto_routable"
	// FilterReasonQuotaExhausted: provider is in the quota_exhausted state
	// with retry_after in the future. The candidate would have been eligible
	// otherwise.
	FilterReasonQuotaExhausted FilterReason = "quota_exhausted"
)

// NoViableCandidateError reports that routing evaluated candidates but every
// one failed a gate.
type NoViableCandidateError struct {
	Rejected int
	Model    string
	Provider string
	Harness  string
	MinPower int
	MaxPower int
}

func (e *NoViableCandidateError) Error() string {
	var pins []string
	if e.Model != "" {
		pins = append(pins, "model="+e.Model)

package routing

import (
	"fmt"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

// Capabilities describes what a (harness, provider, model) tuple can do.
// Populated from harness config + catalog metadata + provider discovery.
type Capabilities struct {
	ContextWindow      int      // resolved tokens; 0 = unknown
	SupportsTools      bool     // supports tool/function calling
	SupportsStreaming  bool     // supports streaming responses
	SupportedReasoning []string // supported public reasoning values
	MaxReasoningTokens int      // 0 means numeric reasoning is unsupported/unknown
	SupportedPerms     []string // {"safe","supervised","unrestricted"} subset
	ExactPinSupport    bool     // accepts exact concrete model pins
	SupportedModels    []string // nil = no static allow-list
}

// HasReasoning returns true if the candidate supports the requested reasoning
// value. Empty, auto, off, and numeric 0 impose no requirement.
func (c Capabilities) HasReasoning(value string) bool {
	policy, err := reasoning.ParseString(value)
	if err != nil {
		return false
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return true
	case reasoning.KindTokens:
		return c.MaxReasoningTokens > 0 && policy.Tokens <= c.MaxReasoningTokens
	case reasoning.KindNamed:
		for _, supported := range c.SupportedReasoning {
			normalized, err := reasoning.Normalize(supported)
			if err == nil && normalized == policy.Value {
				return true
			}
		}
		return false
	default:
		return false
	}
}

// HasPermissions returns true if the candidate supports the requested level.
// An empty permission level always returns true.
func (c Capabilities) HasPermissions(perm string) bool {
	if perm == "" {
		return true
	}
	for _, p := range c.SupportedPerms {
		if strings.EqualFold(p, perm) {
			return true
		}
	}
	return false
}

// HasModel returns true when the exact model pin is within the static
// harness allow-list. A nil allow-list means the harness delegates validation
// to provider-side model checks.
func (c Capabilities) HasModel(model string) bool {
	if c.SupportedModels == nil || model == "" {
		return true
	}
	for _, supported := range c.SupportedModels {
		if supported == model {
			return true
		}
	}
	return false
}

// CheckGating applies all capability gates against a request and returns
// the first failure reason (free-form string for diagnostics) plus the
// typed FilterReason category for the failure. Returns ("", FilterReasonEligible)
// when all gates pass.
//
// The typed return is the authoritative classification — callers must not
// re-classify by parsing the string. The string is for human-readable
// diagnostics only.
//
// Fixes ddx-4817edfd subtree: pre-dispatch capability check covering
// context window, tool support, effort, permissions.
func CheckGating(cap Capabilities, req Request) (string, FilterReason) {
	// Context window gating: if the request declares prompt size or an effort
	// that implies a minimum context, reject candidates that can't fit.
	minCtx := req.MinContextWindow()
	if minCtx > 0 && cap.ContextWindow > 0 && cap.ContextWindow < minCtx {
		return fmt.Sprintf("context window %d < required %d", cap.ContextWindow, minCtx), FilterReasonContextTooSmall
	}

	// Tool-calling support gating.
	if req.RequiresTools && !cap.SupportsTools {
		return "tool calling not supported", FilterReasonNoToolSupport
	}

	if !cap.HasReasoning(req.Reasoning) {
		return fmt.Sprintf("reasoning %q not supported", req.Reasoning), FilterReasonReasoningUnsupported
	}

	// Permissions support gating.
	if !cap.HasPermissions(req.Permissions) {
		return fmt.Sprintf("permissions %q not supported", req.Permissions), FilterReasonScoredBelowTop
	}

	if req.Model != "" && !cap.HasModel(req.Model) {
		return "model not in harness allow-list", FilterReasonScoredBelowTop
	}

	// Exact-pin gating: an explicit Model field requires ExactPinSupport.
	if req.Model != "" && req.ModelRef == "" && !cap.ExactPinSupport {
		return "exact model pin not supported", FilterReasonScoredBelowTop
	}

	return "", FilterReasonEligible
}

// CheckPowerEligibility applies catalog-power gates for unpinned automatic
// routing. Any explicit hard route pin (harness, provider, or model) bypasses
// this gate so caller-chosen routes are never broadened or overridden by
// power policy.
func CheckPowerEligibility(lookup func(string) (ModelEligibility, bool), model string, req Request) (string, FilterReason) {
	if req.Model != "" || req.Provider != "" || req.Harness != "" || lookup == nil {
		return "", FilterReasonEligible
	}
	if model == "" {
		return "model has no catalog power metadata", FilterReasonPowerMissing
	}
	eligibility, ok := lookup(model)
	if !ok {
		if req.MinPower > 0 || req.MaxPower > 0 {
			return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
		}
		return "", FilterReasonEligible
	}
	if eligibility.ExactPinOnly {
		return fmt.Sprintf("model %q is exact-pin-only", model), FilterReasonExactPinOnly
	}
	if !eligibility.AutoRoutable {
		if eligibility.Power <= 0 {
			return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
		}
		return fmt.Sprintf("model %q is not auto-routable", model), FilterReasonNotAutoRoutable
	}
	if req.MinPower > 0 && eligibility.Power < req.MinPower {
		return fmt.Sprintf("model %q power %d < min_power %d", model, eligibility.Power, req.MinPower), FilterReasonBelowMinPower
	}
	if req.MaxPower > 0 && eligibility.Power > req.MaxPower {
		return fmt.Sprintf("model %q power %d > max_power %d", model, eligibility.Power, req.MaxPower), FilterReasonAboveMaxPower
	}
	return "", FilterReasonEligible
}

// resolveRequestReasoning returns a copy of req with Reasoning resolved to the
// catalog's surface_policy reasoning_default for the request's profile/surface
// when the request asks for Reasoning=auto. This must run before CheckGating
// so candidates that only support a different reasoning level (e.g. an
// off-only variant under a profile whose surface default is "high") are
// correctly disqualified by the capability gate. Other Reasoning values
// (unset, off, named, numeric) are left untouched, preserving the existing
// behavior of those code paths.
func resolveRequestReasoning(req Request, surface string, resolver func(profile, surface string) (string, bool)) Request {
	if resolver == nil || req.Profile == "" {
		return req
	}
	policy, err := reasoning.ParseString(req.Reasoning)
	if err != nil || policy.Kind != reasoning.KindAuto {
		return req
	}
	resolved, ok := resolver(req.Profile, surface)
	if !ok || resolved == "" {
		return req
	}
	out := req
	out.Reasoning = resolved
	return out
}

package routing

// costClassRank maps cost class to numeric rank (lower = cheaper).
var costClassRank = map[string]int{
	"local":        0,
	"cheap":        1,
	"medium":       2,
	"expensive":    3,
	"experimental": -1,
	"":             2, // unknown = medium
}

// scorePolicy returns a score for a candidate under the named profile.
// Higher is better.
//
// Routing priority policy (ported from DDx routing.go):
//   - cheap: local + low-cost preferred; subscription-within-quota next.
//   - standard: balanced; light local/subscription preference to avoid spend.
//   - smart: quality first; cloud capability wins; no local bonus.
//
// The policy is profile-aware AND provider-aware via providerBias hooks
// supplied by the caller (cooldown demotion, observation perf bias,
// provider-affinity bias).
func scorePolicy(profile string, cand candidateInternal) float64 {
	base := 100.0
	cr := costClassRank[cand.CostClass]
	withinQuota := cand.IsSubscription && cand.QuotaOK

	switch profile {
	case "cheap":
		if cand.CostClass == "local" {
			base += 40
		} else if withinQuota {
			base += 20
		}
		base -= float64(cr) * 30

	case "standard":
		if cand.CostClass == "local" {
			base += 25
		} else if withinQuota {
			base += 15
		}
		base -= float64(cr) * 10

	case "smart":
		// Quality first; higher cost rank approximates higher capability.
		base += float64(cr) * 20
		if withinQuota {
			base += 5
		}

	default:
		// Treat unspecified as standard.
		if cand.CostClass == "local" {
			base += 25
		} else if withinQuota {
			base += 15
		}
		base -= float64(cr) * 10
	}

	// Provider preference bias.
	switch cand.ProviderPreference {
	case "local-first", "":
		if cand.CostClass == "local" {
			base += 30
		}
	case "subscription-first":
		if cand.IsSubscription && cand.QuotaOK {
			base += 30
		}
	}

	// Quota signals.
	if cand.IsSubscription {
		// Stale quota penalty.
		if cand.QuotaStale {
			base -= 15
		}

		// Trend-based adjustments.
		switch cand.QuotaTrend {
		case "exhausting":
			base -= 40
		case "burning":
			base -= 20
		case "healthy":
			base += 10
		}

		// Quota near-limit penalty (>= 80% used).
		if cand.QuotaPercentUsed >= 80 {
			base -= float64(cand.QuotaPercentUsed-80) * 2
		}
	}

	// Historical success-rate adjustment (only when sufficient samples).
	if cand.HistoricalSuccessRate >= 0 {
		switch {
		case cand.HistoricalSuccessRate >= 0.8:
			base += 20
		case cand.HistoricalSuccessRate < 0.5:
			base -= 30
		}
	}
	if cand.ProviderSuccessRate >= 0 {
		switch {
		case cand.ProviderSuccessRate >= 0.8:
			base += 25
		case cand.ProviderSuccessRate < 0.5:
			base -= 35
		}
	}

	// Cooldown demotion: candidate has had recent failures.
	if cand.InCooldown {
		base -= 50
	}

	// Provider affinity: explicit provider pins are filtered before scoring;
	// this bonus only affects the ordering among still-eligible candidates
	// that share the pinned provider identity.
	if cand.ProviderAffinityMatch {
		base += 15
	}

	if cand.Power > 0 {
		base += float64(cand.Power) * 12
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens > 0 {
		costPenalty := cand.CostUSDPer1kTokens * 500
		if costPenalty > 60 {
			costPenalty = 60
		}
		base -= costPenalty
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens == 0 {
		switch {
		case cand.CostClass == "local":
			base += 15
		case cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80:
			base += 15
		}
	}
	if cand.Power >= 9 && cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80 {
		base += 20
	}

	// Context headroom is a ranking signal for otherwise eligible candidates.
	// A larger spare window gives the model more room for completion and tool
	// overhead, so reward it modestly without overpowering the primary policy.
	if cand.ContextHeadroom > 0 {
		headroomBonus := float64(cand.ContextHeadroom) / 1000.0
		if headroomBonus > 30 {
			headroomBonus = 30
		}
		base += headroomBonus
	}

	// Observation-derived perf bias.
	if cand.ObservedTokensPerSec > 0 {
		// Small additive bonus, scaled.
		base += cand.ObservedTokensPerSec / 100.0
	}
	if cand.ObservedLatencyMS > 0 {
		// Latency is a tiebreaker-scale signal: faster endpoints gain a small
		// bonus while very slow endpoints receive little benefit.
		base += 1000.0 / cand.ObservedLatencyMS
	}
	if cand.CostClass == "experimental" {
		base -= 75
	}

	return base
}

// Command fiz is a standalone CLI that wraps the fizeau library.
package main

import (
	"fmt"
	"os"
	"runtime/debug"

	"github.com/DocumentDrivenDX/fizeau/agentcli"
)

// Version info set via -ldflags.
var (
	Version   = "dev"
	BuildTime = ""
	GitCommit = ""
)

func main() {
	version := effectiveVersion(Version)
	cmd := agentcli.MountCLI(
		agentcli.WithStdin(os.Stdin),
		agentcli.WithStdout(os.Stdout),
		agentcli.WithStderr(os.Stderr),
		agentcli.WithVersion(version, BuildTime, GitCommit),
	)
	args := os.Args[1:]
	if agentcli.NeedsLegacyPassthrough(args) {
		args = append([]string{"--"}, args...)
	}
	cmd.SetArgs(args)
	if err := cmd.Execute(); err != nil {
		if code, ok := agentcli.ExitCode(err); ok {
			os.Exit(code)
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func effectiveVersion(defaultVersion string) string {
	if defaultVersion != "" && defaultVersion != "dev" {
		return defaultVersion
	}
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return defaultVersion
	}
	if info.Main.Version == "" || info.Main.Version == "(devel)" {
		return defaultVersion
	}
	return info.Main.Version
}

// buildHarnessCandidates expands one HarnessEntry into 1..N candidates, one
// per (harness, provider, resolved-model) tuple.
func buildHarnessCandidates(h HarnessEntry, req Request, in Inputs) []rankedCandidate {
	caps := Capabilities{
		SupportsTools:      h.SupportsTools,
		SupportedReasoning: h.SupportedReasoning,
		MaxReasoningTokens: h.MaxReasoningTokens,
		SupportedPerms:     h.SupportedPerms,
		ExactPinSupport:    h.ExactPinSupport,
		SupportedModels:    h.SupportedModels,
	}

	if !h.Available {
		return []rankedCandidate{{
			out: Candidate{
				Harness:      h.Name,
				CostSource:   CostSourceUnknown,
				Reason:       "harness not available",
				FilterReason: FilterReasonUnhealthy,
			},
			internal: candidateInternal{Harness: h.Name, CostClass: h.CostClass, CostSource: CostSourceUnknown},
		}}
	}

	histRate, hasHist := in.HistoricalSuccess[h.Name]
	if !hasHist {
		histRate = -1
	}

	// Enumerate providers. For harnesses with no providers (subprocess harnesses
	// with vendor-managed billing), emit a single virtual provider entry.
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}

	out := make([]rankedCandidate, 0, len(providers))
	minCtx := req.MinContextWindow()
	for _, p := range providers {
		model, reason := resolveModel(h, p, req, in)
		ctxWin := 0
		ctxSrc := ContextSourceUnknown
		if p.ContextWindows != nil {
			if v, ok := p.ContextWindows[model]; ok {
				ctxWin = v
			}
		}
		if ctxWin > 0 && p.ContextWindowSources != nil {
			if src, ok := p.ContextWindowSources[model]; ok && src != "" {
				ctxSrc = src
			}
		}
		if ctxWin == 0 && p.ContextWindow > 0 {
			ctxWin = p.ContextWindow
			if p.ContextWindowSource != "" {
				ctxSrc = p.ContextWindowSource
			}
		}
		if ctxWin == 0 && model != "" {
			ctxWin = 131072
			ctxSrc = ContextSourceDefault
		}
		if model == "" {
			ctxSrc = ContextSourceUnknown
		}
		entryCaps := caps
		entryCaps.ContextWindow = ctxWin
		entryCaps.SupportsTools = caps.SupportsTools || p.SupportsTools
		if len(p.DiscoveredIDs) > 0 {
			entryCaps.SupportedModels = nil
		}

		key := ProviderModelKey(p.Name, p.EndpointName, model)
		obs := in.ObservedSpeedTPS[key]
		if obs == 0 && p.EndpointName != "" {
			obs = in.ObservedSpeedTPS[ProviderModelKey(p.Name, "", model)]
		}
		providerSuccessRate := -1.0
		if rate, ok := in.ProviderSuccessRate[key]; ok {
			providerSuccessRate = rate
		} else if p.EndpointName != "" {
			if rate, ok := in.ProviderSuccessRate[ProviderModelKey(p.Name, "", model)]; ok {
				providerSuccessRate = rate
			}
		}
		latencyMS := in.ObservedLatencyMS[key]
		if latencyMS == 0 && p.EndpointName != "" {
			latencyMS = in.ObservedLatencyMS[ProviderModelKey(p.Name, "", model)]
		}
		power := candidatePower(in.ModelEligibility, model)
		endpointLoad := EndpointLoad{}
		if in.EndpointLoadResolver != nil {
			loadProvider, loadEndpoint := candidateLoadIdentity(h, p)
			if resolved, ok := in.EndpointLoadResolver(loadProvider, loadEndpoint, model); ok {
				endpointLoad = resolved
			}
		} else if load, ok := in.EndpointLoads[key]; ok {
			endpointLoad = load
		}

		gateReq := resolveRequestReasoning(req, h.Surface, in.ReasoningResolver)

		eligible := true
		var filterReason FilterReason
		if reason == "" {
			// Subscription quota is a hard availability gate and must be
			// reported before catalog metadata gates. An exhausted Claude/Codex/
			// Gemini account is never a viable candidate, regardless of whether
			// the resolved model has complete power metadata.
			if h.IsSubscription && !h.SubscriptionOK {
				eligible = false
				reason = h.QuotaReason
				if reason == "" {
					if h.QuotaStale {
						reason = "subscription quota unavailable"
					} else {
						reason = "subscription quota exhausted"
					}
				}
				filterReason = FilterReasonUnhealthy
			} else if g, fr := CheckPowerEligibility(in.ModelEligibility, model, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			} else if g, fr := CheckGating(entryCaps, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			}
		} else {
			eligible = false
			// resolveModel rejection — model resolution is a capability
			// mismatch with no specific public category, so fall through
			// to the catch-all.
			filterReason = FilterReasonScoredBelowTop
		}

		// Hard preference filtering.
		if eligible {
			switch req.ProviderPreference {
			case ProviderPreferenceLocalOnly:
				if !h.IsLocal {
					eligible = false
					reason = "preference is local-only"
					filterReason = FilterReasonUnhealthy
				}
			case ProviderPreferenceSubscriptionOnly:
				if !h.IsSubscription {
					eligible = false
					reason = "preference is subscription-only"
					filterReason = FilterReasonUnhealthy
				}
			}
		}

		if eligible && req.Provider != "" && req.Provider != candidateProviderIdentity(h, p) {
			// Hard provider pin: reject every other provider identity, even
			// when a non-pinned candidate would otherwise score higher.
			eligible = false
			reason = fmt.Sprintf("provider override requires %s", req.Provider)
			filterReason = FilterReasonPinMismatch
		}

		inCooldown := false
		if p.Name != "" && p.InCooldown {
			inCooldown = true
		} else if p.Name != "" && in.CooldownDuration > 0 {
			if failedAt, ok := in.ProviderCooldowns[p.Name]; ok {
				if in.Now.Sub(failedAt) < in.CooldownDuration {
					inCooldown = true
				}
			}
		}

		// Provider quota-exhausted gate. The state machine lives in the
		// service layer; the engine consumes the projected map of
		// provider-name → retry_after. Apply only when the candidate would
		// otherwise have been eligible — disqualifying an already-rejected
		// candidate with a different reason would lose the original signal.
		var quotaExhaustedRetryAfter time.Time
		if eligible {
			providerKey := candidateProviderIdentity(h, p)
			if providerKey != "" && len(in.ProviderQuotaExhaustedUntil) > 0 {
				if retryAfter, ok := in.ProviderQuotaExhaustedUntil[providerKey]; ok && retryAfter.After(in.Now) {
					eligible = false
					reason = fmt.Sprintf("provider %s quota exhausted until %s", providerKey, retryAfter.Format(time.RFC3339))
					filterReason = FilterReasonQuotaExhausted
					quotaExhaustedRetryAfter = retryAfter
				}
			}
		}

		ci := candidateInternal{
			Harness:               h.Name,
			Provider:              p.Name,
			EndpointName:          p.EndpointName,
			ServerInstance:        p.ServerInstance,
			Model:                 model,
			CostClass:             candidateCostClass(h, p),
			CostUSDPer1kTokens:    p.CostUSDPer1kTokens,
			CostSource:            normalizeCostSource(p.CostSource),
			Power:                 power,
			ContextLength:         ctxWin,
			ContextSource:         ctxSrc,
			IsSubscription:        h.IsSubscription,
			QuotaOK:               h.QuotaOK,
			QuotaPercentUsed:      h.QuotaPercentUsed,
			QuotaStale:            h.QuotaStale,
			QuotaTrend:            h.QuotaTrend,
			SubscriptionOK:        h.SubscriptionOK,
			HistoricalSuccessRate: histRate,
			ProviderSuccessRate:   providerSuccessRate,
			ObservedTokensPerSec:  obs,
			ObservedLatencyMS:     latencyMS,
			InCooldown:            inCooldown || h.InCooldown,
			ProviderAffinityMatch: req.Provider != "" && req.Provider == candidateProviderIdentity(h, p),
			ProviderPreference:    req.ProviderPreference,
			EndpointLoad:          endpointLoad.NormalizedLoad,
			EndpointLoadFresh:     endpointLoad.UtilizationFresh,
			EndpointSaturated:     endpointLoad.UtilizationSaturated,
		}
		if eligible && ctxWin > 0 && minCtx > 0 {
			ci.ContextHeadroom = ctxWin - minCtx
		}
		out = append(out, rankedCandidate{
			out: Candidate{
				Harness:            h.Name,
				Provider:           p.Name,
				Endpoint:           p.EndpointName,
				ServerInstance:     p.ServerInstance,
				Model:              model,
				CostUSDPer1kTokens: p.CostUSDPer1kTokens,
				CostSource:         normalizeCostSource(p.CostSource),
				Power:              power,
				ContextLength:      ctxWin,
				ContextSource:      ctxSrc,
				Eligible:           eligible,
				Reason:             reason,
				FilterReason:       filterReason,
				LatencyMS:          latencyMS,
				SuccessRate:        providerSuccessRate,
				CostClass:          candidateCostClass(h, p),
				SpeedTPS:           obs,
				ContextHeadroom:    ci.ContextHeadroom,
				QuotaOK:            h.QuotaOK,
				QuotaPercentUsed:   h.QuotaPercentUsed,
				QuotaTrend:         h.QuotaTrend,
			},
			internal:                 ci,
			quotaExhaustedRetryAfter: quotaExhaustedRetryAfter,
		})
	}
	return out
}

func candidatePower(lookup func(string) (ModelEligibility, bool), model string) int {
	if lookup == nil || model == "" {
		return 0
	}
	eligibility, ok := lookup(model)
	if !ok {
		return 0
	}
	return eligibility.Power
}

func candidateProviderIdentity(h HarnessEntry, p ProviderEntry) string {
	if p.Name != "" {
		return p.Name
	}
	return h.Name
}

func candidateLoadIdentity(h HarnessEntry, p ProviderEntry) (string, string) {
	provider := candidateProviderIdentity(h, p)
	endpoint := p.ServerInstance
	if base, ep, ok := strings.Cut(provider, "@"); ok && base != "" {
		provider = base
		if endpoint == "" {
			endpoint = ep
		}

		return right
	}
	if right <= 0 || left < right {
		return left
	}
	return right
}

func abs(v float64) float64 {
	if v < 0 {
		return -v
	}
	return v
}

// routeStatusComponents mirrors fizeau.RouteCandidateComponents in the
// route-status JSON envelope. Operators read these to answer "why did the
// router pick X?" without parsing the free-form Reason string.
type routeStatusComponents struct {
	Power            int     `json:"power"`
	Cost             float64 `json:"cost"`
	CostClass        string  `json:"cost_class,omitempty"`
	LatencyMS        float64 `json:"latency_ms"`
	SpeedTPS         float64 `json:"speed_tps"`
	SuccessRate      float64 `json:"success_rate"`
	QuotaOK          bool    `json:"quota_ok"`
	QuotaPercentUsed int     `json:"quota_percent_used"`
	QuotaTrend       string  `json:"quota_trend,omitempty"`
	Capability       float64 `json:"capability"`
	ContextHeadroom  int     `json:"context_headroom"`
}

type routeStatusCandidate struct {
	Harness       string                           `json:"harness,omitempty"`
	Provider      string                           `json:"provider"`
	Endpoint      string                           `json:"endpoint,omitempty"`
	Model         string                           `json:"model"`
	Score         float64                          `json:"score"`
	ContextLength int                              `json:"context_length"`
	ContextSource string                           `json:"context_source"`
	Components    routeStatusComponents            `json:"components"`
	Utilization   rootfizeau.RouteUtilizationState `json:"utilization,omitempty"`
	Eligible      bool                             `json:"eligible"`
	FilterReason  string                           `json:"filter_reason"`
	Reason        string                           `json:"reason,omitempty"`
	CostSource    string                           `json:"cost_source,omitempty"`
	Winner        bool                             `json:"winner"`
}

type routeStatusPowerPolicy struct {
	Profile  string `json:"profile,omitempty"`
	MinPower int    `json:"min_power,omitempty"`
	MaxPower int    `json:"max_power,omitempty"`
}

type routeStatusOutput struct {
	Profile          string                           `json:"profile,omitempty"`
	Model            string                           `json:"model,omitempty"`
	ModelRef         string                           `json:"model_ref,omitempty"`
	Provider         string                           `json:"provider,omitempty"`
	Harness          string                           `json:"harness,omitempty"`
	MinPower         int                              `json:"min_power,omitempty"`
	MaxPower         int                              `json:"max_power,omitempty"`
	PowerPolicy      routeStatusPowerPolicy           `json:"power_policy,omitempty"`
	SelectedEndpoint string                           `json:"selected_endpoint,omitempty"`
	Sticky           rootfizeau.RouteStickyState      `json:"sticky,omitempty"`
	Utilization      rootfizeau.RouteUtilizationState `json:"utilization,omitempty"`
	Winner           *routeStatusCandidate            `json:"winner,omitempty"`
	Candidates       []routeStatusCandidate           `json:"candidates"`
	Error            string                           `json:"error,omitempty"`
}

// cmdRouteStatus reports the routing engine's eligible-candidate trace for a
// requested intent (per ADR-005 §5). It calls service.ResolveRoute rather than
// enumerating route tables; score components and filter reasons come from the
// engine itself, not a parallel CLI implementation.
func cmdRouteStatus(workDir string, args []string) int {
	fs := flag.NewFlagSet("route-status", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	profile := fs.String("profile", "", "Routing profile (cheap|standard|smart)")
	model := fs.String("model", "", "Pin a specific model")
	modelRef := fs.String("model-ref", "", "Model catalog reference")
	provider := fs.String("provider", "", "Pin a specific provider")
	harness := fs.String("harness", "", "Pin a specific harness")
	minPower := fs.Int("min-power", 0, "Minimum catalog model power for automatic routing")
	maxPower := fs.Int("max-power", 0, "Maximum catalog model power for automatic routing")
	jsonOut := fs.Bool("json", false, "Output JSON")
	overrides := fs.Bool("overrides", false, "Print override_class_breakdown over a time window (ADR-006). "+
		"Operator-driven feedback loop; automatic learning is a future ADR. "+
		"Buckets with high override count and high outcome success rate suggest auto-routing is "+
		"picking suboptimally for that prompt class. Buckets with high override count and low "+
		"outcome success rate suggest users are pinning out of habit; consider UI nudges.")
	since := fs.String("since", "", "Time window for --overrides mode (Go duration, e.g. 24h, 168h). Default 7d (168h).")
	axis := fs.String("axis", "", "With --overrides, filter breakdown rows to overrides on this axis (harness|provider|model).")
	if err := fs.Parse(args); err != nil {
		return 2
	}

	if *overrides {
		return cmdRouteStatusOverrides(workDir, *since, *axis, *jsonOut)
	}
	if err := rootfizeau.ValidatePowerBounds(*minPower, *maxPower); err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 2
	}

	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	svc, err := rootfizeau.New(rootfizeau.ServiceOptions{
		ServiceConfig: agentConfig.NewServiceConfig(cfg, workDir),
		SessionLogDir: sessionLogDir(workDir, cfg),
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	decision, resolveErr := svc.ResolveRoute(ctx, rootfizeau.RouteRequest{
		Profile:  *profile,
		Model:    *model,
		ModelRef: *modelRef,
		Provider: *provider,
		Harness:  *harness,
		MinPower: *minPower,
		MaxPower: *maxPower,
	})

	out := routeStatusOutput{
		Profile:  *profile,
		Model:    *model,
		ModelRef: *modelRef,
		Provider: *provider,
		Harness:  *harness,
		MinPower: *minPower,
		MaxPower: *maxPower,
		PowerPolicy: routeStatusPowerPolicy{
			Profile:  *profile,
			MinPower: *minPower,
			MaxPower: *maxPower,
		},
		Candidates: []routeStatusCandidate{},
	}
	if resolveErr != nil {
		out.Error = resolveErr.Error()
	}
	if decision != nil {
		out.SelectedEndpoint = decision.Endpoint
		out.Sticky = decision.Sticky
		out.Utilization = decision.Utilization
		out.PowerPolicy = routeStatusPowerPolicy{
			Profile:  decision.PowerPolicy.Profile,
			MinPower: decision.PowerPolicy.MinPower,
			MaxPower: decision.PowerPolicy.MaxPower,
		}
		winnerSet := decision.Harness != "" || decision.Provider != "" || decision.Model != ""
		for _, c := range decision.Candidates {
			entry := routeStatusCandidate{
				Harness:       c.Harness,
				Provider:      c.Provider,
				Endpoint:      c.Endpoint,
				Model:         c.Model,
				Score:         c.Score,
				ContextLength: c.ContextLength,
				ContextSource: c.ContextSource,
				Eligible:      c.Eligible,
				FilterReason:  c.FilterReason,
				Reason:        c.Reason,
				CostSource:    c.CostSource,
				Utilization:   c.Utilization,
				Components: routeStatusComponents{
					Power:            c.Components.Power,
					Cost:             c.Components.Cost,
					CostClass:        c.Components.CostClass,
					LatencyMS:        c.Components.LatencyMS,
					SpeedTPS:         c.Components.SpeedTPS,
					SuccessRate:      c.Components.SuccessRate,
					QuotaOK:          c.Components.QuotaOK,
					QuotaPercentUsed: c.Components.QuotaPercentUsed,
					QuotaTrend:       c.Components.QuotaTrend,
					Capability:       c.Components.Capability,
					ContextHeadroom:  c.Components.ContextHeadroom,
				},
			}
			if winnerSet && out.Winner == nil &&
				c.Harness == decision.Harness &&
				c.Provider == decision.Provider &&
				c.Model == decision.Model {
				entry.Winner = true
				w := entry
				out.Winner = &w
			}
			out.Candidates = append(out.Candidates, entry)
		}
	}

package agentcli

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/DocumentDrivenDX/fizeau"
)

// TestRouteStatusOverridesJSONStable snapshots the JSON envelope shape so
// downstream operator tooling (dashboards, alerts) can rely on it. New
// keys may be added behind a flag — never silently changed.
func TestRouteStatusOverridesJSONStable(t *testing.T) {
	start := time.Date(2026, 4, 18, 0, 0, 0, 0, time.UTC)
	end := time.Date(2026, 4, 25, 0, 0, 0, 0, time.UTC)
	envelope := routeStatusOverridesOutput{
		Since:                    "168h",
		WindowStart:              start,
		WindowEnd:                end,
		AxisFilter:               "harness",
		AutoAcceptanceRate:       0.4,
		OverrideDisagreementRate: 0.5,
		TotalRequests:            5,
		TotalOverrides:           3,
		OverrideClassBreakdown: []fizeau.OverrideClassBucket{
			{
				PromptFeatureBucket: "tokens=small,tools=no,reasoning=none",
				Axis:                "harness",
				Match:               false,
				Count:               2,
				SuccessOutcomes:     1,
				FailedOutcomes:      1,
			},
		},
	}

	var buf bytes.Buffer
	writeRouteStatusOverridesJSON(&buf, envelope)

	// Round-trip parse: schema must decode into a known shape, with every
	// AC-required key present at the top level.
	var generic map[string]json.RawMessage
	if err := json.Unmarshal(buf.Bytes(), &generic); err != nil {
		t.Fatalf("unmarshal: %v\n%s", err, buf.String())
	}
	requiredTopLevel := []string{
		"since",
		"window_start",
		"window_end",
		"axis_filter",
		"auto_acceptance_rate",
		"override_disagreement_rate",
		"total_requests",
		"total_overrides",
		"override_class_breakdown",
	}
	for _, k := range requiredTopLevel {
		if _, ok := generic[k]; !ok {
			t.Errorf("required key %q missing from JSON envelope:\n%s", k, buf.String())
		}
	}

	// Bucket schema: every documented field must round-trip.
	var bkt []fizeau.OverrideClassBucket
	if err := json.Unmarshal(generic["override_class_breakdown"], &bkt); err != nil {
		t.Fatalf("decode breakdown: %v", err)
	}
	if len(bkt) != 1 {
		t.Fatalf("breakdown len = %d, want 1", len(bkt))
	}
	got := bkt[0]
	if got.PromptFeatureBucket != "tokens=small,tools=no,reasoning=none" {
		t.Errorf("PromptFeatureBucket = %q", got.PromptFeatureBucket)
	}
	if got.Axis != "harness" || got.Match != false || got.Count != 2 {
		t.Errorf("bucket fields lost in round-trip: %+v", got)
	}
	if got.SuccessOutcomes != 1 || got.FailedOutcomes != 1 {
		t.Errorf("outcome aggregates lost in round-trip: %+v", got)
	}

	// Verify the bucket JSON keys themselves are stable: per ADR-006 §5
	// the breakdown is the operator pivot, so its key names are part of
	// the contract.
	var bucketGeneric []map[string]json.RawMessage
	if err := json.Unmarshal(generic["override_class_breakdown"], &bucketGeneric); err != nil {
		t.Fatalf("decode bucket generic: %v", err)
	}
	requiredBucketKeys := []string{
		"prompt_feature_bucket",
		"axis",
		"match",
		"count",
		"success_outcomes",
		"stalled_outcomes",
		"failed_outcomes",
		"cancelled_outcomes",
		"unknown_outcomes",
	}
	for _, k := range requiredBucketKeys {
		if _, ok := bucketGeneric[0][k]; !ok {
			t.Errorf("bucket key %q missing:\n%s", k, buf.String())
		}
	}

	// Snapshot the JSON output; trailing newline tolerated.
	want := `{
  "since": "168h",
  "window_start": "2026-04-18T00:00:00Z",
  "window_end": "2026-04-25T00:00:00Z",
  "axis_filter": "harness",
  "auto_acceptance_rate": 0.4,
  "override_disagreement_rate": 0.5,
  "total_requests": 5,
  "total_overrides": 3,
  "override_class_breakdown": [
    {
      "prompt_feature_bucket": "tokens=small,tools=no,reasoning=none",
      "axis": "harness",
      "match": false,
      "count": 2,
      "success_outcomes": 1,
      "stalled_outcomes": 0,
      "failed_outcomes": 1,
      "cancelled_outcomes": 0,
      "unknown_outcomes": 0
    }
  ]
}
`
	if got := buf.String(); got != want {
		t.Errorf("JSON envelope drift.\n--- got ---\n%s\n--- want ---\n%s", got, want)
	}

	// Empty axis_filter must omit the field (omitempty contract).
	envelope.AxisFilter = ""
	buf.Reset()
	writeRouteStatusOverridesJSON(&buf, envelope)
	if strings.Contains(buf.String(), `"axis_filter"`) {
		t.Errorf("empty axis_filter should be omitted (omitempty):\n%s", buf.String())
	}
}

